import{c as t,Q as a,j as n,m as o}from"./chunks/framework.BqPkuuVc.js";const r="/assets/edit-event-backup-export.BzH4Mz_z.png",s="/assets/event-list-restore-name.BFXCev2z.png",i="/assets/event-storage-failure.B2XcGhmD.png",k=JSON.parse('{"title":"Backup and restore","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/backup-and-restore.md","filePath":"user/reference/backup-and-restore.md"}'),d={name:"user/reference/backup-and-restore.md"};function h(l,e,c,p,u,g){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="backup-and-restore" tabindex="-1">Backup and restore <a class="header-anchor" href="#backup-and-restore" aria-label="Permalink to &quot;Backup and restore&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers protecting event data and recovering from problems.</p><p>How to back up an event (and when to), how to restore from a backup, and what to do when an event can&#39;t be saved or won&#39;t open.</p><h2 id="card-downloads-are-always-kept-twice" tabindex="-1">Card downloads are always kept twice <a class="header-anchor" href="#card-downloads-are-always-kept-twice" aria-label="Permalink to &quot;Card downloads are always kept twice&quot;">​</a></h2><p>Card downloads are the one part of an event that can&#39;t be typed in again. Once the runner has cleared their card, its punches exist nowhere else. So Manager protects them whether or not you ever take a backup.</p><p><strong>Every card download is saved to disk as a file of its own before anything else happens to it.</strong> Only then is it processed and matched to a competitor. Each read is kept as its own file in the event&#39;s <code>CardDownloads</code> folder, as well as in the event database. That gives you <strong>at least two copies of every card download</strong>, from the moment it&#39;s read.</p><ul><li><strong>This can&#39;t be turned off.</strong> There is no setting for it, and it doesn&#39;t depend on auto backup.</li><li><strong>The file stays even if the download doesn&#39;t.</strong> Deleting a download, or replacing a manual download with an edited one, removes it from the event but leaves its file on disk.</li><li><strong>The files are enough to rebuild from.</strong> Even with no backup at all, an event&#39;s card downloads can be completely recreated from these files alone. <strong>Import from Backup</strong> on the <strong>Card downloads</strong> screen reads them back in (see <a href="#repairing-a-damaged-event">Repairing a damaged event</a>).</li></ul><p>Backups are still worth taking: they hold everything else (entries, classes, courses, overrides, the audit trail) and bring the whole event back in one step. But a card read is never only in one place.</p><h2 id="what-a-backup-is" tabindex="-1">What a backup is <a class="header-anchor" href="#what-a-backup-is" aria-label="Permalink to &quot;What a backup is&quot;">​</a></h2><p>A backup is a single <code>.zip</code> file holding a copy of the <strong>whole event</strong>: its settings, the event database (competitors, teams, card downloads, radio punches), classes, courses and controls, the map, the audit trail, screens and the card-download files. It is a byte-for-byte copy, so a restored event is the same event — results, overrides, notes and all.</p><p>You can take a backup at any time, <strong>including while the event is live</strong>. Manager copies the database in a way that is safe while card downloads and radio punches are still arriving, so you don&#39;t need to pause anything.</p><p>Two things are <strong>not</strong> in a backup:</p><ul><li><strong>Camera recordings</strong> from the <a href="./../screens/info-screens">info displays</a>. They are large and kept on the server only.</li><li><strong>Earlier automatic backups.</strong> Each backup leaves out the event&#39;s own <code>auto-backup/</code> folder, so backups don&#39;t grow inside each other.</li></ul><blockquote><p><strong>Note:</strong> A backup isn&#39;t the same as an export. An <a href="./../after-the-event/exports">export</a> (IOF XML, CSV, <a href="./../advanced/orienteering-json">Orienteering JSON</a>) carries the event&#39;s data for another program to read. Only a backup carries everything needed to bring the event back exactly as it was.</p></blockquote><blockquote><p><strong>Note:</strong> Don&#39;t confuse this with <strong>station backup memory</strong>. That is the record of punches kept inside a SportIdent station, and you read it from the station. See <a href="./../running-the-event/station-memory">Station memory</a>.</p></blockquote><h2 id="three-ways-to-back-up" tabindex="-1">Three ways to back up <a class="header-anchor" href="#three-ways-to-back-up" aria-label="Permalink to &quot;Three ways to back up&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Taken when</th><th>Kept where</th><th>Set up in</th></tr></thead><tbody><tr><td><strong>Manual backup</strong></td><td>When you click it</td><td>Downloaded to your browser, or saved on the server</td><td>The event&#39;s card in the <strong>Events</strong> list</td></tr><tr><td><strong>Auto backup</strong></td><td>Every few minutes while the event is <strong>live</strong></td><td>The event&#39;s own folder, on the server&#39;s disk</td><td><strong>Settings → Auto backup</strong> (defaults) and the event&#39;s <strong>Backup &amp; export</strong> tab</td></tr><tr><td><strong>External drive backup</strong></td><td>Every few minutes while the event is <strong>live</strong></td><td>A USB stick or external disk plugged into the server</td><td>The event&#39;s <strong>Backup &amp; export</strong> tab</td></tr></tbody></table><p>Auto backup protects you against mistakes: a bulk change you regret, a bad import. It doesn&#39;t protect against the server&#39;s disk failing, because the backups sit on that same disk. That is what the external drive is for. For a championship, use both — and consider a <a href="./../running-the-event/live-standby">live standby</a>, a second computer that holds a copy up to the last second and can carry on the event in a few minutes.</p><h3 id="taking-a-manual-backup" tabindex="-1">Taking a manual backup <a class="header-anchor" href="#taking-a-manual-backup" aria-label="Permalink to &quot;Taking a manual backup&quot;">​</a></h3><ol><li>Open the <strong>Events</strong> list.</li><li>On the event&#39;s card, click the <strong>Backup event</strong> icon (a downward arrow).</li><li>Choose where the backup goes: <ul><li><strong>Download</strong> — the zip is saved by your browser, usually to your <strong>Downloads</strong> folder, on the device you&#39;re using. Nothing is kept on the server.</li><li><strong>Save on server</strong> — the zip is saved in the <code>Backups</code> folder of Manager&#39;s data folder, on the server computer. It then appears in the <strong>From server</strong> list when you restore (see below).</li></ul></li></ol><p>Backup files are named after the event id, the event name and the time the backup was taken (in UTC), for example <code>2026-02-19.01__City_Sprint_Championships__20260219T043000Z.zip</code>. Rename one if you like; only backups saved on the server need to keep this name to appear in the <strong>From server</strong> list.</p><h3 id="auto-backup" tabindex="-1">Auto backup <a class="header-anchor" href="#auto-backup" aria-label="Permalink to &quot;Auto backup&quot;">​</a></h3><p>Auto backup is <strong>off</strong> until you turn it on. While it&#39;s on, Manager writes a backup of the live event into an <code>auto-backup/</code> folder inside the event&#39;s own folder, at the interval you choose, and deletes the oldest ones beyond the number you keep.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Choices</th><th>Default</th></tr></thead><tbody><tr><td><strong>Enable auto backup</strong></td><td>on / off</td><td>off</td></tr><tr><td><strong>Backup frequency</strong></td><td>5, 10, 15, 30 or 60 minutes</td><td>15 minutes</td></tr><tr><td><strong>Backups to keep</strong></td><td>1, 2, 5, 10 or <strong>All</strong></td><td>5</td></tr></tbody></table><p><strong>Settings → Auto backup</strong> holds the defaults. Each <strong>new</strong> event starts with them. After that the event has its own copy, which you change on the event&#39;s <strong>Event details → Backup &amp; export</strong> tab. Changing the defaults later doesn&#39;t change events you&#39;ve already created.</p><p>Things worth knowing:</p><ul><li><strong>Auto backups only run while the event is live.</strong> Nothing is backed up automatically during setup or after you finish the event. Take a manual backup at those times (see <a href="#when-to-back-up">When to back up</a>).</li><li><strong>The first auto backup is taken one interval after the event starts</strong>, not at the moment you click <strong>Start event</strong>.</li><li><strong>A change on a live event takes effect straight away.</strong> Switching auto backup on or off, or changing its frequency, restarts the schedule. A new <strong>Backups to keep</strong> value applies after the next backup.</li><li><strong>Old backups are deleted only after a new one has been written.</strong> If backups stop working (a full disk, say), the ones already taken are never cleared away.</li><li><strong>Only this event&#39;s own backups are counted and deleted.</strong> Any other zip you put in the folder yourself is left alone.</li></ul><h3 id="external-drive-backup" tabindex="-1">External drive backup <a class="header-anchor" href="#external-drive-backup" aria-label="Permalink to &quot;External drive backup&quot;">​</a></h3><p>An external drive backup copies a backup of the live event onto a USB stick or external disk plugged into the <strong>computer running meshO Manager</strong>. Your event then survives the server&#39;s own disk dying.</p><p><img src="'+r+'" alt="The Backup &amp; export tab of Event details, with Backup to external drive switched on and a drive called BACKUPS chosen"></p><p>To set it up:</p><ol><li>Plug the drive into the server computer.</li><li>Open the event&#39;s <strong>Event details</strong> and go to the <strong>Backup &amp; export</strong> tab.</li><li>Under <strong>External drive backup</strong>, switch on <strong>Backup to external drive</strong>.</li><li>Choose the drive from the <strong>Drive</strong> list. Click <strong>Refresh</strong> if you plugged it in after opening the dialog. The box below the list confirms the choice, for example &quot;Backups will be copied to BACKUPS. 30.0 GB free.&quot;</li><li>Set <strong>Backup frequency</strong> (10, 15, 30, 60 or 120 minutes; the default is 30) and <strong>Backups to keep</strong> (1, 2, 5, 10 or All; the default is 5).</li><li>Click <strong>Save</strong>.</li></ol><p>The external drive backup is set per event. There is no default for it in Settings, so turn it on for each event that needs it. It has its own schedule, separate from auto backup, because a USB stick is much slower than the server&#39;s disk. Taking the local backup every 10 minutes and the external one every hour is a reasonable split.</p><p>Copies land in a <code>meshO-backups</code> folder on the drive, with one folder per event (<code>meshO-backups/&lt;event id&gt;/</code>). Anything else on the drive is left alone.</p><p><strong>Manager recognises the drive itself, not the slot it&#39;s plugged into.</strong> If you unplug the stick and plug it into a different USB port, Manager finds it there. A <em>different</em> stick in the old port is never written to instead. That&#39;s why a drive with no name or ID can&#39;t be chosen: give it a name (a volume label) and click <strong>Refresh</strong>.</p><p><strong>A problem is never silent.</strong> If a copy is due and the drive is unplugged, full or write-protected, Manager raises an <strong>alert</strong> that says which. The alert disappears on its own once copies resume. The same alert appears if the switch is on but no drive has been chosen.</p><p>The backup is built on the server&#39;s own disk first and only then copied to the drive. A slow stick therefore never holds up card downloads or anything else happening in the live event. If the drive is pulled out halfway through a copy, it never holds a half-written backup that looks complete; the leftover part-file is cleared away by the next copy.</p><blockquote><p><strong>Tip:</strong> Take the stick home at the end of the day, or hand it to someone who isn&#39;t leaving with the server laptop. A backup in the same bag as the laptop doesn&#39;t help if the bag goes missing.</p></blockquote><h2 id="when-to-back-up" tabindex="-1">When to back up <a class="header-anchor" href="#when-to-back-up" aria-label="Permalink to &quot;When to back up&quot;">​</a></h2><p>Auto backup covers the live event. Take a <strong>manual</strong> backup as well:</p><ul><li><strong>Before a risky change</strong>: a re-import of entries or courses, a bulk edit, any <strong>Delete all</strong>, letting an <a href="./ai-assistants-mcp">AI assistant</a> make changes. None of these can be undone, and a backup taken just before is the undo.</li><li><strong>At the end of setup</strong>, before you click <strong>Start event</strong>. Auto backup doesn&#39;t run until the event is live.</li><li><strong>After you finish the event</strong>, once results are final. Keep this one somewhere other than the server: it&#39;s the copy you&#39;ll want in six months&#39; time.</li><li><strong>Before moving the event to another computer</strong> (see <a href="./../event-setup/moving-an-event">Moving an event to another computer</a>).</li></ul><h2 id="where-backups-are-kept" tabindex="-1">Where backups are kept <a class="header-anchor" href="#where-backups-are-kept" aria-label="Permalink to &quot;Where backups are kept&quot;">​</a></h2><p>Manager keeps everything in its data folder on the server computer:</p><table tabindex="0"><thead><tr><th>Computer</th><th>Data folder</th></tr></thead><tbody><tr><td>Windows</td><td><code>C:\\Users\\Public\\Documents\\meshO Manager</code></td></tr><tr><td>macOS</td><td><code>~/Library/Application Support/meshO Manager</code></td></tr><tr><td>Linux</td><td><code>~/.local/share/meshO Manager</code></td></tr></tbody></table><p>Inside it:</p><table tabindex="0"><thead><tr><th>Backup</th><th>Location</th></tr></thead><tbody><tr><td>Manual backups saved on the server</td><td><code>Backups/</code></td></tr><tr><td>Auto backups</td><td><code>Events/&lt;event id&gt;/auto-backup/</code></td></tr><tr><td>Card-download files (always kept, one per read)</td><td><code>Events/&lt;event id&gt;/CardDownloads/</code></td></tr><tr><td>External drive backups</td><td><code>meshO-backups/&lt;event id&gt;/</code> on the drive, not in the data folder</td></tr><tr><td>Manual backups you downloaded</td><td>Wherever your browser saves downloads, on the device you used</td></tr></tbody></table><h2 id="restoring-an-event" tabindex="-1">Restoring an event <a class="header-anchor" href="#restoring-an-event" aria-label="Permalink to &quot;Restoring an event&quot;">​</a></h2><p><strong>Restoring always creates a new event.</strong> It never overwrites or merges into an event you already have. The restored event:</p><ul><li>keeps the original event&#39;s date and gets the next free number on that date (for example, a backup of <code>2026-02-19.01</code> restores as <code>2026-02-19.02</code>);</li><li>is named when you restore it (see below). If the backup was made on <strong>this</strong> computer, the name offered has <strong>(restored)</strong> added, so you can tell the copy from the original beside it. If it came from <strong>another</strong> computer, the name is offered unchanged;</li><li>isn&#39;t connected to the original&#39;s cloud copy. To show it to spectators online, publish it with <strong>Push to cloud</strong> on its event card. It is published as a new event, not as an update to the original&#39;s copy (see <a href="./settings">Settings → Cloud sync</a>).</li></ul><p>To restore:</p><ol><li><p>Open the <strong>Events</strong> list and click <strong>Restore</strong> (next to <strong>New</strong>). On a fresh installation with no events yet, the button is <strong>Restore from backup</strong>, under <strong>New event</strong>.</p></li><li><p>Choose where the backup is:</p><ul><li><strong>Local file</strong> — click the button and pick a <code>.zip</code> from the device you&#39;re using. Use this for a backup you downloaded, an auto backup, or a backup from an external drive.</li><li><strong>From server</strong> — pick from the backups saved with <strong>Save on server</strong>.</li></ul></li><li><p>Check the <strong>Event name</strong>. The box explains the name it offers:</p><ul><li>made on this computer: the original name with <strong>(restored)</strong> added;</li><li>made on another computer: the original name unchanged;</li><li>a backup from an older version of Manager that doesn&#39;t record where it was made: <strong>(restored)</strong> added, in case the original is also on this computer.</li></ul><p>Change it if you like (at least 3 characters), then click <strong>Restore</strong>. <strong>Back</strong> returns to choosing a backup.</p></li><li><p>The restored event opens.</p></li></ol><p><img src="'+s+'" alt="The name step of Restore from backup: &quot;Restoring “Autumn Sprint”. This backup was made on another computer, so the event keeps its name.&quot; with the Event name box showing Autumn Sprint"></p><blockquote><p><strong>Note:</strong> <strong>Local file</strong> means local to the device your <em>browser</em> is on, which may not be the server. To restore an auto backup or an external drive backup from another laptop, copy the zip to that laptop first, or restore from a browser on the server itself.</p></blockquote><h3 id="if-the-backup-was-taken-while-the-event-was-live" tabindex="-1">If the backup was taken while the event was live <a class="header-anchor" href="#if-the-backup-was-taken-while-the-event-was-live" aria-label="Permalink to &quot;If the backup was taken while the event was live&quot;">​</a></h3><p>An auto backup, an external drive backup, or a manual backup taken during the race is a picture of an event that was still running. When you restore it, the restored event shows as <strong>interrupted</strong>. From its dashboard you can <strong>Resume event</strong>, to carry on timing in it, or <strong>Mark finished</strong>. See <a href="./../running-the-event/dashboard">the dashboard</a>.</p><h3 id="backups-from-other-versions" tabindex="-1">Backups from other versions <a class="header-anchor" href="#backups-from-other-versions" aria-label="Permalink to &quot;Backups from other versions&quot;">​</a></h3><p>A backup taken by an <strong>older</strong> version of Manager restores in a newer one; the event is upgraded when it&#39;s opened. A backup taken by a <strong>newer</strong> version is refused by an older one. Update Manager on the computer you&#39;re restoring to.</p><h3 id="moving-an-event-to-another-computer" tabindex="-1">Moving an event to another computer <a class="header-anchor" href="#moving-an-event-to-another-computer" aria-label="Permalink to &quot;Moving an event to another computer&quot;">​</a></h3><p>Handing a set-up event to the person running it, or moving it to the laptop that goes to the event, is a backup and a restore plus a short checklist: checking the name, liveresultat and backups, and setting up the printers and hire cards that belong to the laptop. See <a href="./../event-setup/moving-an-event">Moving an event to another computer</a>.</p><h2 id="when-an-event-can-t-be-saved" tabindex="-1">When an event can&#39;t be saved <a class="header-anchor" href="#when-an-event-can-t-be-saved" aria-label="Permalink to &quot;When an event can&#39;t be saved&quot;">​</a></h2><p>Sometimes the server&#39;s disk stops accepting the event&#39;s changes. The folder may have become read-only, sync software such as OneDrive or Dropbox may have locked a file, antivirus may be blocking Manager, or the disk may be full. Manager then covers every manager screen with <strong>This event can&#39;t be saved</strong>:</p><p><img src="'+i+'" alt="The &quot;This event can&#39;t be saved&quot; message, showing the event folder, what couldn&#39;t be saved, how many changes are held back and the steps to fix it"></p><p><strong>No change is lost while this is showing.</strong> Manager holds every change it couldn&#39;t save, in order. Card downloads and radio punches keep being taken in. Manager also keeps a second copy of the held-back changes outside the event folder; the message shows where.</p><p>To clear it:</p><ol><li>Fix the cause. The message lists what couldn&#39;t be saved and the error, with the usual fixes: <ul><li>make sure the event folder isn&#39;t read-only and your user account can write to it;</li><li>if the folder is inside OneDrive, Dropbox or another synced folder, pause syncing or move Manager&#39;s data to a plain local folder;</li><li>check antivirus or ransomware protection isn&#39;t blocking meshO Manager, and that the disk isn&#39;t full.</li></ul></li><li>Click <strong>Retry</strong>. Manager saves the held-back changes and checks that each one really landed. The message only goes away once they have.</li></ol><p>If you have to close Manager before it&#39;s fixed, the held-back changes aren&#39;t lost. They&#39;re saved the next time the event is opened. However, if the message says the second copy couldn&#39;t be saved either, <strong>keep Manager open</strong> until the problem is fixed. In that case the only copy of those changes is in memory.</p><blockquote><p><strong>Warning:</strong> If the message says the database&#39;s <strong>integrity check failed</strong>, Retry won&#39;t fix it. Keep Manager open and contact meshO support.</p></blockquote><p>The message only appears on the manager screens. The entry desk (<code>/rego</code>) doesn&#39;t show it, but changes made there are held in the same way.</p><h2 id="repairing-a-damaged-event" tabindex="-1">Repairing a damaged event <a class="header-anchor" href="#repairing-a-damaged-event" aria-label="Permalink to &quot;Repairing a damaged event&quot;">​</a></h2><p>Manager has no repair tool that edits a damaged event in place. Recovery means going back to a good copy and replaying what came after it:</p><ul><li><strong>Restore the most recent backup</strong> — usually the newest auto backup or external drive backup. It comes back as a new event, so the damaged one is still there to look at.</li><li><strong>Bring back missing card downloads.</strong> Every card read is kept as its own file in the event&#39;s <code>CardDownloads</code> folder, written before the download was processed (see <a href="#card-downloads-are-always-kept-twice">Card downloads are always kept twice</a>). On <strong>Card downloads</strong>, <strong>Import from Backup</strong> finds any files the event hasn&#39;t loaded and lets you bring them back in. See <a href="./../running-the-event/card-download#import-from-backup">Card download</a>.</li><li><strong>Re-read the SportIdent stations.</strong> Each station&#39;s backup memory holds the punches it recorded, independently of Manager. See <a href="./../running-the-event/station-memory">Station memory</a>.</li><li><strong>Check the <a href="./audit-trail">audit trail</a></strong> of the restored event against what you remember doing. Changes made after the backup was taken need making again.</li></ul><p>If an event won&#39;t open at all, restore it from a backup rather than spending race-day time trying to repair it. Keep the broken event&#39;s folder (don&#39;t delete it) so meshO support can look at it afterwards.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../after-the-event/end-of-event-checklist">End-of-event checklist</a></li><li><a href="./settings">Settings</a></li><li><a href="./troubleshooting">Troubleshooting</a></li><li><a href="./../running-the-event/dashboard">The dashboard</a> — resuming an interrupted event</li><li><a href="./../running-the-event/card-download">Card download</a> — Import from Backup</li><li><a href="./../download-and-install/">Installing meshO Manager</a></li></ul>',74)])])}const b=t(d,[["render",h]]);export{k as __pageData,b as default};
